package com.storypocket.mobile;

import java.net.URI;
import java.util.Locale;

/**
 * Navigation generated by untrusted Instagram web content must never launch a
 * native Instagram intent without a deliberate user action in StoryPocket.
 * Pure Java so redirects can be regression-tested without an Android device.
 */
public final class NavigationPolicy {
    public enum Decision { IN_WEBVIEW, BLOCK_APP_LINK, BLOCK_EXTERNAL_WEB, BLOCK_UNSAFE_SCHEME }
    private NavigationPolicy() { }

    public static Decision decide(String value, boolean mainFrame) {
        if (value == null || value.length() > 8192) return Decision.BLOCK_UNSAFE_SCHEME;
        try {
            URI uri = URI.create(value);
            String scheme = uri.getScheme();
            if (scheme == null) return Decision.BLOCK_UNSAFE_SCHEME;
            scheme = scheme.toLowerCase(Locale.ROOT);
            // Frame navigation should not spawn native apps, either.
            if ("about".equals(scheme) && "about:blank".equalsIgnoreCase(value)) {
                return Decision.IN_WEBVIEW;
            }
            if ("intent".equals(scheme) || "instagram".equals(scheme) ||
                "fb".equals(scheme) || "market".equals(scheme) ||
                "fb-messenger".equals(scheme)) {
                return Decision.BLOCK_APP_LINK;
            }
            if ("https".equals(scheme) && SocialLinks.isSupported(value)) {
                return Decision.IN_WEBVIEW;
            }
            if ("http".equals(scheme) || "https".equals(scheme)) {
                return Decision.BLOCK_EXTERNAL_WEB;
            }
            return Decision.BLOCK_UNSAFE_SCHEME;
        } catch (RuntimeException ignored) {
            return Decision.BLOCK_UNSAFE_SCHEME;
        }
    }
}
